use super::*;

/// Where the money actually goes.
///
/// The two EXCLUSIONS lead, because they are the reason this figure differs from a naive sum of
/// outflows — and a reader who does not know they happened will think the number is wrong.
pub fn render_spending(a: &spending::SpendingAnalysis, read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    if a.outflows.is_empty() {
        out.push_str("no outflows in what has been read\n");
        for n in read_notes {
            out.push_str(&format!("  · {n}\n"));
        }
        return out;
    }
    out.push_str(&format!(
        "{} → {} · {} whole month(s)\n\n  fixed     {} a month — standing charges, already on the calendar\n  variable  {} a month — what an ordinary month actually costs\n",
        a.from, a.to, a.months_observed, m(a.fixed_monthly.minor), m(a.variable_monthly.minor)
    ));
    if !a.categories.is_empty() {
        out.push_str("\n  where the money goes, biggest first:\n");
        for c in &a.categories {
            out.push_str(&format!("    {:<16}{:>12}   {:>10} in a usual month\n", c.category, m(c.total.minor), m(c.typical_month.minor)));
        }
    }
    if !a.uncategorised.is_empty() {
        out.push_str(&format!("\n  {} outflow(s) matched no rule — listed, NOT bucketed as \"other\":\n", a.uncategorised.len()));
        for t in &a.uncategorised {
            out.push_str(&format!("    {} {:<28}{:>10}\n", t.date, clip(&t.description, 28), m(-t.amount.minor)));
        }
    }
    out.push_str("\nWhat was left out, and why:\n");
    for n in &a.notes {
        out.push_str(&format!("  · {n}\n"));
    }
    for n in read_notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}
